-- DEV-001 native lifecycle completion; published 0072 is retained unchanged.
CREATE TABLE nc_webhook_subscription_revisions(subscription_id TEXT PRIMARY KEY REFERENCES nc_subscriptions(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id),revision TEXT NOT NULL);
INSERT INTO nc_webhook_subscription_revisions(subscription_id,customer_id,revision) SELECT id,customer_id,revision FROM nc_subscriptions WHERE origin='native';
CREATE TABLE nc_webhook_invoice_settlements(invoice_id TEXT PRIMARY KEY REFERENCES nc_invoices(id),customer_id TEXT NOT NULL REFERENCES nc_customers(id));
INSERT INTO nc_webhook_invoice_settlements(invoice_id,customer_id) SELECT e.subject,e.customer_id FROM nc_webhook_events e JOIN nc_invoices i ON i.id=e.subject WHERE e.type='invoice.paid' GROUP BY e.subject;
CREATE TABLE nc_webhook_entitlement_state(customer_id TEXT PRIMARY KEY REFERENCES nc_customers(id),basis TEXT NOT NULL,state_json TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE nc_webhook_observation_cursor(singleton INTEGER PRIMARY KEY CHECK(singleton=1),customer_id TEXT NOT NULL DEFAULT '');
INSERT INTO nc_webhook_observation_cursor(singleton) VALUES(1);
DROP TRIGGER nc_webhook_subscription_created;
DROP TRIGGER nc_webhook_subscription_updated;
DROP TRIGGER nc_webhook_invoice_paid;
CREATE TRIGGER nc_webhook_native_subscription AFTER INSERT ON nc_audit BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),CASE WHEN NEW.action='subscription.create' THEN 'subscription.created' ELSE 'subscription.updated' END,s.customer_id,s.id,json_object('type',CASE WHEN NEW.action='subscription.create' THEN 'subscription.created' ELSE 'subscription.updated' END,'data',json_object('id',s.id,'customer_id',s.customer_id,'billing_mode',s.billing_mode,'end_date',s.end_date),'metadata',json_array(json_object('kind','customer','id',s.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=s.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',s.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=s.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NULL),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=s.id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NULL AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) FROM nc_subscriptions s
 WHERE (s.origin='native' AND (s.id=NEW.subject OR s.id=json_extract(NEW.detail,'$.subscription')) AND NOT EXISTS(SELECT 1 FROM nc_webhook_subscription_revisions observed WHERE observed.subscription_id=s.id AND observed.revision=s.revision)) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=s.customer_id AND erased_at IS NOT NULL);
INSERT INTO nc_webhook_subscription_revisions(subscription_id,customer_id,revision) SELECT s.id,s.customer_id,s.revision FROM nc_subscriptions s WHERE s.origin='native' AND (s.id=NEW.subject OR s.id=json_extract(NEW.detail,'$.subscription')) ON CONFLICT(subscription_id) DO UPDATE SET revision=excluded.revision;
END;
CREATE TRIGGER nc_webhook_import_subscription_created AFTER INSERT ON nc_subscriptions WHEN NEW.origin='import' BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'subscription.created',NEW.customer_id,NEW.id,json_object('type','subscription.created','data',json_object('id',NEW.id,'customer_id',NEW.customer_id,'billing_mode',NEW.billing_mode,'end_date',NEW.end_date),'metadata',json_array(json_object('kind','customer','id',NEW.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',NEW.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NULL),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=NEW.id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NULL AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) 
 WHERE (1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.customer_id AND erased_at IS NOT NULL);
END;
