INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'subscription.updated',NEW.customer_id,NEW.id,json_object('type','subscription.updated','data',json_object('id',NEW.id,'customer_id',NEW.customer_id,'billing_mode',NEW.billing_mode,'end_date',NEW.end_date),'metadata',json_array(json_object('kind','customer','id',NEW.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',NEW.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NULL),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=NEW.id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NULL AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) 
 WHERE (1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.customer_id AND erased_at IS NOT NULL);
END;
CREATE TRIGGER nc_webhook_lifecycle AFTER INSERT ON nc_subscription_lifecycle BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'subscription.lifecycle_changed',s.customer_id,NEW.subscription_id,json_object('type','subscription.lifecycle_changed','data',json_object('id',NEW.id,'subscription_id',NEW.subscription_id,'kind',NEW.kind,'effective_date',NEW.effective_date,'until_date',NEW.until_date,'access',NEW.access),'metadata',json_array(json_object('kind','customer','id',s.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=s.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',NEW.subscription_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.subscription_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NULL),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=NEW.subscription_id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NULL AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) FROM nc_subscriptions s
 WHERE (s.id=NEW.subscription_id) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=s.customer_id AND erased_at IS NOT NULL);
END;
CREATE TRIGGER nc_webhook_payment_method AFTER INSERT ON nc_native_collections BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'payment_method.observed',NEW.customer_id,NEW.id,json_object('type','payment_method.observed','data',json_object('id',NEW.id,'customer_id',NEW.customer_id,'invoice_id',NEW.invoice_id,'payment_method_ref',NEW.payment_method_ref),'metadata',json_array(json_object('kind','customer','id',NEW.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id),'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NEW.invoice_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.invoice_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NEW.invoice_id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NEW.invoice_id AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) 
 WHERE (1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.customer_id AND erased_at IS NOT NULL);
END;
CREATE TRIGGER nc_webhook_payment_outcome AFTER UPDATE ON nc_native_collections WHEN OLD.status<>NEW.status AND NEW.status IN ('declined','customer_action_required','uncertain') BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),CASE WHEN NEW.status='uncertain' THEN 'payment.uncertain' ELSE 'payment.failed' END,NEW.customer_id,NEW.id,json_object('type',CASE WHEN NEW.status='uncertain' THEN 'payment.uncertain' ELSE 'payment.failed' END,'data',json_object('id',NEW.id,'customer_id',NEW.customer_id,'invoice_id',NEW.invoice_id,'status',NEW.status,'error_code',NEW.error_code,'amount_cents',NEW.amount_cents),'metadata',json_array(json_object('kind','customer','id',NEW.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id),'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NEW.invoice_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.invoice_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NEW.invoice_id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=(SELECT subscription_id FROM nc_invoices WHERE id=NEW.invoice_id) UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NEW.invoice_id AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) 
 WHERE (1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.customer_id AND erased_at IS NOT NULL);
END;
CREATE TRIGGER nc_webhook_refund AFTER UPDATE ON nc_prepaid_refunds WHEN OLD.status<>NEW.status AND NEW.status='refunded' BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'payment.refunded',NEW.customer_id,NEW.id,json_object('type','payment.refunded','data',json_object('id',NEW.id,'customer_id',NEW.customer_id,'invoice_id',NEW.purchase_invoice_id,'amount_cents',NEW.amount_cents,'refund_ref',NEW.refund_ref),'metadata',json_array(json_object('kind','customer','id',NEW.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=NEW.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',NEW.subscription_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=NEW.subscription_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',NEW.purchase_invoice_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=NEW.purchase_invoice_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NEW.payment_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NEW.payment_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NEW.credit_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NEW.credit_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=NEW.purchase_invoice_id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_prices p WHERE p.id IN(SELECT price_id FROM nc_items WHERE subscription_id=NEW.subscription_id UNION SELECT price_id FROM nc_invoice_lines WHERE invoice_id=NEW.purchase_invoice_id AND price_id IS NOT NULL)),'[]'))))),CAST(unixepoch('subsec')*1000 AS INTEGER) 
 WHERE (1) AND EXISTS(SELECT 1 FROM nc_webhook_endpoints WHERE enabled=1) AND NOT EXISTS(SELECT 1 FROM nc_privacy_context) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND applying=1) AND NOT EXISTS(SELECT 1 FROM nc_customers WHERE id=NEW.customer_id AND erased_at IS NOT NULL);
END;
CREATE TRIGGER nc_webhook_settled_allocation AFTER INSERT ON nc_allocations WHEN 1 BEGIN
INSERT INTO nc_webhook_events(id,type,customer_id,subject,payload_json,created_at)
 SELECT lower(hex(randomblob(16))),'invoice.paid',i.customer_id,i.id,json_object('type','invoice.paid','data',json_object('id',i.id,'invoice_id',i.id,'customer_id',i.customer_id,'amount_cents',i.total_cents,'cash_allocated_cents',COALESCE((SELECT SUM(amount_cents) FROM nc_allocations WHERE invoice_id=i.id),0),'custody','recorded-ledger-settlement'),'metadata',json_array(json_object('kind','customer','id',i.customer_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='customer' AND record_id=i.customer_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','subscription','id',i.subscription_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='subscription' AND record_id=i.subscription_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','invoice','id',i.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='invoice' AND record_id=i.id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','payment','id',NEW.payment_id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='payment' AND record_id=NEW.payment_id ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-note','id',NULL,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=NULL ORDER BY revision DESC LIMIT 1),'{}'))),json_object('kind','credit-notes','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','credit-note','id',cn.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='credit-note' AND record_id=cn.id ORDER BY revision DESC LIMIT 1),'{}'))))) FROM nc_credit_notes cn WHERE cn.invoice_id=i.id),'[]'))),json_object('kind','prices','objects',json(COALESCE((SELECT json_group_array(json(json_object('kind','price','id',p.id,'metadata',json(COALESCE((SELECT metadata_json FROM nc_metadata_revisions WHERE kind='price' AND record_id=p